values
  ('money2020-usa', 'Money20/20 USA', '2026-10-25', '2026-10-28', 'Las Vegas', 'United States', 'North America', 'Payments', 11500, 'https://us.money2020.com', 'The largest gathering of the global payments and fintech industry. Exhibitors span PSPs, card networks, cross-border platforms and multi-currency providers, with a heavy concentration of commercial decision-makers.', 'approved', 'Official site — Who Attends, Sponsors, Agenda', 'high', '{"companyFit":{"score":100,"signals":["PSPs","Card networks","Cross-border platforms","Multi-currency providers"],"evidence":"Exhibitor and sponsor lists are dominated by PSPs, card networks, cross-border payment platforms and multi-currency providers — directly Grain use cases."},"buyerFit":{"score":100,"signals":["Heads of Payments","VP Finance","Treasury leaders","Fintech C-suite"],"evidence":"Dense concentration of Heads of Payments, VP Finance and treasury leaders; C-suite fintech attendance is a headline of the event."},"agendaRelevance":{"score":75,"signals":["Cross-border payments","FX","Money movement"],"evidence":"Several tracks cover cross-border payments, FX and money movement, though the agenda also spans lending, crypto and identity."},"networking":{"score":100,"signals":["1:1 matchmaking","Meetings platform","Hosted programs","Receptions"],"evidence":"Structured matchmaking, a dedicated meetings platform, hosted programs and extensive evening receptions."}}'::jsonb, true, false),
  ('money2020-europe', 'Money20/20 Europe', '2027-06-08', '2027-06-10', 'Amsterdam', 'Netherlands', 'Europe', 'Payments', 8000, 'https://europe.money2020.com', 'Europe''s flagship payments and fintech show. A strong European concentration of PSPs, cross-border and multi-currency platforms alongside the commercial leaders who buy for them.', 'approved', 'Official site — Who Attends, Sponsors, Agenda', 'high', '{"companyFit":{"score":100,"signals":["European PSPs","Cross-border platforms","Multi-currency providers"],"evidence":"European PSPs, cross-border and multi-currency platforms are heavily represented among exhibitors and sponsors."},"buyerFit":{"score":100,"signals":["Payments leadership","Finance leaders","European fintech execs"],"evidence":"Payments and finance leadership across European fintechs and platforms attend in force."},"agendaRelevance":{"score":75,"signals":["Cross-border payments","Money movement"],"evidence":"Strong cross-border and money-movement tracks within a broad payments agenda."},"networking":{"score":100,"signals":["Meetings platform","1:1 matchmaking","Receptions"],"evidence":"Meetings platform, matchmaking and extensive receptions."}}'::jsonb, true, false),
  ('sibos-2026', 'Sibos', '2026-10-12', '2026-10-15', 'Frankfurt', 'Germany', 'Europe', 'Payments', 11000, 'https://www.sibos.com', 'Swift-organized global banking and financial infrastructure event. Cross-border payments, correspondent banking and FX are central themes, with a treasury- and banking-heavy audience.', 'approved', 'Official site — Programme, Delegate profile', 'high', '{"companyFit":{"score":75,"signals":["Global banks","Market infrastructures","Large corporates"],"evidence":"Global banks, market infrastructures and large corporates dominate. FX/cross-border relevance is high, but the audience skews to banking institutions over the mid-market platforms Grain often serves."},"buyerFit":{"score":100,"signals":["Treasury leaders","Correspondent banking","Payments heads"],"evidence":"Dense concentration of treasury, correspondent-banking and payments leadership."},"agendaRelevance":{"score":100,"signals":["Cross-border payments","FX","Correspondent banking"],"evidence":"Cross-border payments, FX and correspondent banking are core themes of the programme."},"networking":{"score":75,"signals":["Community sessions","Meeting spaces","Stand meetings"],"evidence":"Structured community sessions, meeting spaces and stand-based meetings, with less 1:1 matchmaking than commercial fintech shows."}}'::jsonb, true, false),
  ('eurofinance-itm', 'EuroFinance International Treasury Management', '2026-10-07', '2026-10-09', 'Barcelona', 'Spain', 'Europe', 'Treasury & Finance', 2500, 'https://www.eurofinance.com', 'Europe''s leading corporate treasury conference. The audience is overwhelmingly treasurers and CFOs from multinationals managing real FX exposure.', 'approved', 'Official site — Who Attends, Agenda', 'high', '{"companyFit":{"score":75,"signals":["Corporate treasuries","Multinationals","Real FX exposure"],"evidence":"Attendees are corporate treasurers from large multinationals with genuine FX exposure — strong fit, though skewed to enterprise corporates rather than payment platforms."},"buyerFit":{"score":100,"signals":["Treasurers","Heads of Treasury","CFOs"],"evidence":"The audience is overwhelmingly Treasurers, Heads of Treasury and CFOs — Grain’s primary buyers."},"agendaRelevance":{"score":100,"signals":["FX risk","Currency management","Cross-border cash"],"evidence":"FX risk, currency management and cross-border cash are core agenda themes."},"networking":{"score":75,"signals":["Meetings app","Structured networking","Receptions"],"evidence":"Structured networking, a meetings app and evening receptions."}}'::jsonb, true, false),
  ('afp-annual', 'AFP Annual Conference', '2026-10-18', '2026-10-21', 'San Diego', 'United States', 'North America', 'Treasury & Finance', 6000, 'https://www.afponline.org', 'The Association for Financial Professionals’ flagship US event for corporate treasury and finance teams, with dedicated FX and international treasury content.', 'approved', 'Official site — Attendee profile, Sessions', 'high', '{"companyFit":{"score":75,"signals":["US corporate treasury","Large enterprises","Finance teams"],"evidence":"Corporate treasury and finance teams from large US enterprises. Strong buyer fit; company profile skews domestic, so cross-border exposure varies by attendee."},"buyerFit":{"score":100,"signals":["Treasurers","Assistant Treasurers","FP&A leaders"],"evidence":"Treasurers, Assistant Treasurers and FP&A leaders make up the core audience."},"agendaRelevance":{"score":75,"signals":["FX sessions","International treasury"],"evidence":"Dedicated FX and international-treasury sessions within a broad treasury/finance agenda."},"networking":{"score":75,"signals":["Roundtables","Structured networking","Large expo"],"evidence":"Structured networking, roundtables and a large expo floor."}}'::jsonb, true, false),
  ('mpe-berlin', 'Merchant Payments Ecosystem (MPE)', '2027-03-16', '2027-03-18', 'Berlin', 'Germany', 'Europe', 'Payments', 1500, 'https://www.merchantpaymentsecosystem.com', 'A focused merchant-payments event bringing together PSPs, acquirers and cross-border payment specialists around acquiring, FX and payment optimization.', 'approved', 'Official site — Attendees, Agenda', 'high', '{"companyFit":{"score":100,"signals":["PSPs","Acquirers","Cross-border specialists"],"evidence":"A tightly focused merchant-payments audience: PSPs, acquirers and cross-border payment specialists."},"buyerFit":{"score":75,"signals":["Payments leaders","Merchant payments teams"],"evidence":"Strong payments-leadership presence, with fewer pure treasury/CFO buyers."},"agendaRelevance":{"score":100,"signals":["Cross-border acquiring","FX","Payment optimization"],"evidence":"Cross-border acquiring, FX and payment optimization are central agenda themes."},"networking":{"score":75,"signals":["1:1 meetings","Focused networking"],"evidence":"Structured 1:1 meetings and focused networking across a compact event."}}'::jsonb, true, false),
  ('singapore-fintech-festival', 'Singapore FinTech Festival', '2026-11-11', '2026-11-13', 'Singapore', 'Singapore', 'Asia-Pacific', 'Fintech', 60000, 'https://www.fintechfestival.sg', 'One of the world''s largest fintech gatherings. Enormous reach including many cross-border and multi-currency players, diluted by a very broad fintech, policy and investor crowd.', 'approved', 'Official site — Overview, Programme', 'medium', '{"companyFit":{"score":75,"signals":["Cross-border players","Multi-currency fintechs","Broad fintech crowd"],"evidence":"Huge fintech audience including many cross-border payment and multi-currency players, though diluted by a very broad fintech and policy crowd."},"buyerFit":{"score":75,"signals":["Payments decision-makers","Finance leaders","Regulators & investors"],"evidence":"Strong presence of payments and finance decision-makers alongside regulators, investors and technologists."},"agendaRelevance":{"score":50,"signals":["Cross-border payments","Broad: AI, policy, crypto"],"evidence":"Cross-border payments feature, but within a sprawling agenda spanning AI, policy, crypto and inclusion."},"networking":{"score":100,"signals":["Matchmaking platform","Investor programs","Hosted sessions"],"evidence":"Dedicated matchmaking platform, investor and hosted programs, and extensive structured networking."}}'::jsonb, true, false),
  ('seamless-middle-east', 'Seamless Middle East', '2027-05-12', '2027-05-13', 'Dubai', 'United Arab Emirates', 'Middle East', 'Payments', 20000, 'https://seamless-middle-east.com', 'A large payments, fintech, e-commerce and retail event for the MENA region, with real cross-border flows but a broad, mixed audience.', 'approved', 'Official site — Visitor profile, Agenda', 'medium', '{"companyFit":{"score":75,"signals":["Payments & e-commerce","MENA cross-border flows","Retail vendors"],"evidence":"Large payments and e-commerce audience with genuine cross-border flows across MENA, mixed with retail and identity vendors."},"buyerFit":{"score":50,"signals":["Senior payments leaders","E-commerce leaders","Mixed seniority"],"evidence":"Senior payments and e-commerce leaders attend, but the crowd is broad and includes many technical and mid-level roles."},"agendaRelevance":{"score":50,"signals":["Cross-border payments","Broad payments & retail"],"evidence":"Cross-border payments appears as a theme within a wide payments/retail/e-commerce program."},"networking":{"score":75,"signals":["Meetings program","Large exhibition"],"evidence":"Structured networking, a meetings program and a large exhibition floor."}}'::jsonb, true, false),
  ('phocuswright', 'The Phocuswright Conference', '2026-11-16', '2026-11-19', 'Fort Lauderdale', 'United States', 'North America', 'Travel', 2000, 'https://www.phocuswright.com', 'The leading travel-industry conference. Travel platforms, OTAs and wholesalers carry material cross-border and multi-currency exposure, viewed through a travel-commerce lens.', 'approved', 'Official site — Attendees, Agenda', 'medium', '{"companyFit":{"score":75,"signals":["Travel platforms","OTAs","Wholesalers","Cross-border FX exposure"],"evidence":"Travel platforms, OTAs and wholesalers with material cross-border and multi-currency exposure, viewed broadly through travel commerce."},"buyerFit":{"score":50,"signals":["Travel executives","Product leaders","Few finance buyers"],"evidence":"Senior travel executives and product leaders attend; finance/treasury buyers are present but not the primary audience."},"agendaRelevance":{"score":50,"signals":["Travel payments","FX in distribution sessions"],"evidence":"Payments and FX surface within travel-distribution and fintech sessions, not as a core theme."},"networking":{"score":75,"signals":["Structured meetings","Hosted sessions","Receptions"],"evidence":"Structured meetings, hosted sessions and receptions."}}'::jsonb, true, false),
  ('shoptalk-europe', 'Shoptalk Europe', '2027-06-02', '2027-06-04', 'Barcelona', 'Spain', 'Europe', 'E-commerce & Marketplaces', 4000, 'https://shoptalk.com/europe', 'A major retail and e-commerce event. Global marketplaces and cross-border retailers attend, but the audience is predominantly commercial and merchandising rather than finance.', 'approved', 'Official site — Who Attends, Meetup program', 'medium', '{"companyFit":{"score":75,"signals":["Global marketplaces","Cross-border retailers","Broad retail crowd"],"evidence":"Global marketplaces and cross-border retailers with international money flows, mixed with a broad retail and brand audience."},"buyerFit":{"score":25,"signals":["Commercial & merchandising","Product leaders","Few finance buyers"],"evidence":"Commercial, merchandising and product leaders dominate; finance and payments buyers are rare."},"agendaRelevance":{"score":25,"signals":["Retail & commerce focus","Payments peripheral"],"evidence":"International payments appear only peripherally within a retail and commerce agenda."},"networking":{"score":100,"signals":["Hosted-meetings program","Algorithmic 1:1 matchmaking"],"evidence":"Signature hosted-meetings program with algorithmic 1:1 matchmaking."}}'::jsonb, true, false),
